<script setup lang="ts">
import { reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { apiSend, errorMessage, refreshSession } from '../api';
const router = useRouter();
const form = reactive({ email: '', password: '', code: '' });
const loading = ref(false), sending = ref(false), error = ref(''), notice = ref('');
async function login() { error.value=''; notice.value=''; if(!form.email.trim()){ error.value='Email is required.'; return;} if(!form.password && !form.code){ error.value='Enter a password or one-time code.'; return;} loading.value=true; try { await apiSend('/api/login','POST',{ email: form.email, password: form.password || undefined, code: form.code || undefined }); await refreshSession(); router.push('/dashboard'); } catch(err){ error.value=errorMessage(err);} finally{ loading.value=false; } }
async function sendCode() { error.value=''; notice.value=''; if(!form.email.trim()){ error.value='Email is required before requesting a code.'; return;} sending.value=true; try { await apiSend('/api/login','POST',{ email: form.email, sendCode: true }); notice.value='A login code was sent if the account is ready.'; } catch(err){ error.value=errorMessage(err);} finally{ sending.value=false; } }
</script>
<template><section class="hero"><div><p class="pill">Welcome back</p><h1 class="text-4xl">Log in to review your dashboard and matches.</h1><p class="text-muted">Use your password, request a one-time code, or enter a code that was already emailed.</p></div><form class="card" @submit.prevent="login" aria-labelledby="login-title"><h2 id="login-title" class="text-2xl">Log in</h2><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><div class="field"><label for="login-email">Email</label><input id="login-email" v-model="form.email" class="input" type="email" autocomplete="email" required /></div><div class="field"><label for="login-password">Password</label><input id="login-password" v-model="form.password" class="input" type="password" autocomplete="current-password" /></div><div class="field"><label for="login-code">One-time code</label><input id="login-code" v-model="form.code" class="input" inputmode="numeric" autocomplete="one-time-code" /></div><div class="actions"><button class="button" :disabled="loading">{{ loading ? 'Logging in…' : 'Log in' }}</button><button class="button secondary" type="button" :disabled="sending" @click="sendCode">{{ sending ? 'Sending…' : 'Email me a code' }}</button></div></form></section></template>
